package canteen;
import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.io.*;import java.nio.file.*;import java.time.LocalDateTime;import java.time.format.DateTimeFormatter;
public class BackupFrame extends JFrame {
 private final String user,role;private DefaultTableModel model;private JTable table;private final Path folder=Paths.get("backups").toAbsolutePath();
 public BackupFrame(String user,String role){this.user=user;this.role=role;if(!AuditLog.isAdmin(role)){AuditLog.requireAdmin(null,role);dispose();return;}AppStyle.setWindowIcon(this);setTitle("PIET | Database Backup & Restore");setSize(850,570);setLocationRelativeTo(null);JPanel p=AppStyle.page("Database backup & restore");JLabel note=new JLabel("Backups are stored locally in: "+folder);note.setForeground(AppStyle.MUTED);JPanel top=new JPanel(new BorderLayout());top.setOpaque(false);top.add(note,BorderLayout.CENTER);JPanel buttons=new JPanel(new FlowLayout(FlowLayout.LEFT));buttons.setOpaque(false);JButton backup=AppStyle.button("Create backup",AppStyle.BLUE),restore=AppStyle.button("Restore selected backup",new Color(190,55,65)),refresh=AppStyle.button("Refresh history",AppStyle.NAVY);buttons.add(backup);buttons.add(restore);buttons.add(refresh);top.add(buttons,BorderLayout.SOUTH);model=new DefaultTableModel(new String[]{"Backup file","Size (KB)","Modified"},0){public boolean isCellEditable(int r,int c){return false;}};table=new JTable(model);AppStyle.styleTable(table);JPanel center=new JPanel(new BorderLayout(8,8));center.setOpaque(false);center.add(top,BorderLayout.NORTH);center.add(new JScrollPane(table),BorderLayout.CENTER);p.add(center,BorderLayout.CENTER);add(p);backup.addActionListener(e->createBackup());restore.addActionListener(e->restore());refresh.addActionListener(e->load());load();}
 private String dbName(){String u=System.getenv("PIET_DB_URL");if(u==null||u.isBlank())u="jdbc:mysql://localhost:3306/piet_canteen_db";int a=u.indexOf("://");int slash=u.indexOf('/',a+3);if(slash<0)return "piet_canteen_db";String n=u.substring(slash+1).split("[?;]")[0];return n.isBlank()?"piet_canteen_db":n;}
 private boolean createBackup(){try{Files.createDirectories(folder);String file="piet_canteen_"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss"))+".sql";Path out=folder.resolve(file);String userEnv=System.getenv().getOrDefault("PIET_DB_USER","root"),pass=System.getenv().getOrDefault("PIET_DB_PASSWORD","");ProcessBuilder pb=new ProcessBuilder("mysqldump","--user="+userEnv,"--databases",dbName(),"--routines","--triggers","--single-transaction");pb.redirectOutput(out.toFile());pb.redirectErrorStream(false);pb.environment().put("MYSQL_PWD",pass);Process pr=pb.start();String err=new String(pr.getErrorStream().readAllBytes());int exit=pr.waitFor();if(exit!=0||Files.size(out)==0){Files.deleteIfExists(out);throw new IOException("mysqldump failed. Ensure MySQL client utilities are installed and on PATH. "+err);}AuditLog.record(user,"DATABASE_BACKUP_CREATED",file);JOptionPane.showMessageDialog(this,"Backup created:\n"+out);load();return true;}catch(Exception e){JOptionPane.showMessageDialog(this,"Backup failed. Install MySQL client utilities and check DB credentials.\n"+e.getMessage(),"Backup error",JOptionPane.ERROR_MESSAGE);return false;}}
 private void restore(){int row=table.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Select a backup first.");return;}String file=model.getValueAt(table.convertRowIndexToModel(row),0).toString();Path chosen=folder.resolve(file);if(!Files.isRegularFile(chosen)||!file.endsWith(".sql")){JOptionPane.showMessageDialog(this,"Invalid backup file.");return;}int ok=JOptionPane.showConfirmDialog(this,"Restore "+file+"? The current database will first be backed up. This operation replaces database contents.","Confirm restore",JOptionPane.YES_NO_OPTION,JOptionPane.WARNING_MESSAGE);if(ok!=JOptionPane.YES_OPTION)return;if(!createBackup())return;try{String userEnv=System.getenv().getOrDefault("PIET_DB_USER","root"),pass=System.getenv().getOrDefault("PIET_DB_PASSWORD","");ProcessBuilder pb=new ProcessBuilder("mysql","--user="+userEnv,dbName());pb.redirectInput(chosen.toFile());pb.redirectErrorStream(true);pb.environment().put("MYSQL_PWD",pass);Process pr=pb.start();String output=new String(pr.getInputStream().readAllBytes());int exit=pr.waitFor();if(exit!=0)throw new IOException(output);AuditLog.record(user,"DATABASE_RESTORED",file);JOptionPane.showMessageDialog(this,"Restore completed. Restart the application and verify the data.");}catch(Exception e){JOptionPane.showMessageDialog(this,"Restore failed: "+e.getMessage(),"Restore error",JOptionPane.ERROR_MESSAGE);}}
 private void load(){model.setRowCount(0);try{Files.createDirectories(folder);try(DirectoryStream<Path> ds=Files.newDirectoryStream(folder,"*.sql")){for(Path f:ds)model.addRow(new Object[]{f.getFileName().toString(),String.format("%.1f",Files.size(f)/1024.0),Files.getLastModifiedTime(f).toString()});}}catch(IOException e){JOptionPane.showMessageDialog(this,e.getMessage());}}
}
